// Token robust aus der Auth-Antwort extrahieren (analog P96):
// die Antwort ist entweder { data: '<token>' } oder { access_token: '<token>' }.
const auth = $('Auth edoobox').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
if (!token) {
  throw new Error('Kein Token in der edoobox-Auth-Antwort enthalten.');
}
// Kategorie aus der Vorlagen-Antwort extrahieren.
// GET /v2/offer/{id} liefert { data: { <id>: { record } } } bzw. { data: [] }.
const roh = $input.first().json;
let d = roh.data ?? roh;
while (d && typeof d === 'object' && !Array.isArray(d)) {
  const keys = Object.keys(d);
  if (keys.length === 1 && d[keys[0]] && typeof d[keys[0]] === 'object') {
    d = d[keys[0]];
    continue;
  }
  break;
}
if (Array.isArray(d)) d = d[0] ?? {};
const category = d.category;
if (!category) {
  throw new Error('Keine Kategorie in der Vorlage gefunden.');
}
return [{ json: { token, category, name: d.name } }];

// Neue Offer-ID aus der Duplicate-Antwort extrahieren (analog P96 entpacken).
// POST /v2/offer/{template}/duplicate liefert { data: { <id>: { record } } }
// bzw. { data: [] }.
const dup = $('Duplicate Offer').first().json;
const vorlage = $('Vorlage normalisieren').first().json;

let d = dup.data ?? dup;
while (d && typeof d === 'object' && !Array.isArray(d)) {
  const keys = Object.keys(d);
  if (keys.length === 1 && d[keys[0]] && typeof d[keys[0]] === 'object') {
    d = d[keys[0]];
    continue;
  }
  break;
}
if (Array.isArray(d)) d = d[0] ?? {};

const newOfferId = d.id ?? d.offer_id ?? dup.offer_id ?? dup.data?.id;
if (!newOfferId) {
  throw new Error('Keine neue Angebots-ID in der Duplicate-Antwort gefunden: ' + JSON.stringify(dup).slice(0, 500));
}

return [{
  json: {
    token: vorlage.token,
    category: vorlage.category,
    name: vorlage.name || d.name,
    template_offer_id: 'offer_8d72df08692f_10460260010',
    offer_id: String(newOfferId)
  }
}];

// Vorlagen-Preise (Node 'Vorlagen-Preise lesen') in je ein Item { data: { ...pflichtfelder, offer: new_offer_id } } umwandeln.
// Nur die von edoobox V2 fuer POST /v2/price akzeptierten Pflichtfelder werden weitergereicht:
//   title, price (bzw. amount), status, offer.
// Alle uebrigen Vorlagen-Felder (id, offer_id, created_at, updated_at, ...) werden verworfen,
// da unerwartete Felder bei edoobox zu HTTP 402 ED80100 fuehren.
function extractRows(roh) {
  let d = roh;
  if (d && typeof d === 'object' && !Array.isArray(d) && d.data !== undefined) {
    d = d.data;
  }
  if (d && typeof d === 'object' && !Array.isArray(d) && Array.isArray(d.rows)) {
    return d.rows;
  }
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') {
    const entries = Object.entries(d);
    if (entries.length > 0) {
      const rows = entries
        .map(([k, v]) => {
          if (v && typeof v === 'object' && !Array.isArray(v)) {
            const rec = (v.record && typeof v.record === 'object') ? v.record : v;
            return { id: rec.id ?? k, ...rec };
          }
          return null;
        })
        .filter(Boolean);
      if (rows.length > 0) return rows;
    }
    return [d];
  }
  return [];
}

const newOfferId = $('Duplicate normalisieren').first().json.offer_id;
if (!newOfferId) throw new Error('Keine neue Angebots-ID (new_offer_id) vorhanden.');

const roh = $('Vorlagen-Preise lesen').first().json;
const rows = extractRows(roh).filter(r => r && typeof r === 'object');

if (rows.length === 0) {
  const msg = 'Keine Vorlagen-Preise gefunden. Roh-Payload: ' + JSON.stringify(roh);
  console.log('[P97 Preise aufbereiten] ' + msg);
  return [{ json: { warning: true, message: msg, rawPayload: roh } }];
}

// Whitelist der von edoobox V2 fuer Preise akzeptierten Pflichtfelder.
const erlaubteFelder = ['title', 'price', 'amount', 'status'];

return rows.map(r => {
  const felder = {};
  for (const f of erlaubteFelder) {
    if (r[f] !== undefined && r[f] !== null) felder[f] = r[f];
  }
  // 'price' hat Vorrang vor 'amount' - nur eines der beiden Felder senden.
  if (felder.price === undefined && felder.amount !== undefined) {
    felder.price = felder.amount;
  }
  delete felder.amount;
  felder.offer = newOfferId;
  return { json: { data: felder } };
});

// Standard-0-EUR-Preis des neuen Angebots ermitteln: alle Preise des neuen Angebots,
// die NICHT soeben aus der Vorlage angelegt wurden (IDs aus den POST-Antworten).
function idsAus(body) {
  const d = body && body.data !== undefined ? body.data : body;
  if (typeof d === 'string' || typeof d === 'number') return [String(d)];
  if (!d || typeof d !== 'object') return [];
  if (Array.isArray(d)) return d.flatMap(x => idsAus({ data: x }));
  if (d.id !== undefined) return [String(d.id)];
  return Object.entries(d).map(([k, v]) => (v && typeof v === 'object' && v.id !== undefined) ? String(v.id) : String(k));
}

const angelegt = new Set($('Preis anlegen').all().flatMap(i => idsAus(i.json)));
if (angelegt.size === 0) {
  throw new Error('Keine IDs der angelegten Preise ermittelbar - Dummy-Loeschung abgebrochen.');
}

const roh = $input.first().json;
const d = roh.data ?? roh;
let rows = [];
if (Array.isArray(d)) {
  rows = d;
} else if (d && typeof d === 'object') {
  rows = Object.entries(d).map(([k, v]) => (v && typeof v === 'object') ? { id: v.id ?? k, ...v } : null).filter(Boolean);
}

const dummies = rows.filter(r => {
  if (r.id === undefined || angelegt.has(String(r.id))) return false;
  const betrag = Number(r.price ?? r.amount ?? r.value ?? 0);
  return !(betrag > 0);
});

return dummies.map(r => ({ json: { price_id: String(r.id) } }));

// Vorlagen-Termine (Node 'Vorlagen-Termine lesen') in je ein Item { data: { ...termin_felder, offer: new_offer_id } } umwandeln.
// Robustes Entpacken aller üblichen edoobox-V2-Rückgabestrukturen:
//   items[0].json.data (Array), items[0].json.data.rows, items[0].json.rows,
//   flache Liste items direkt oder Objekt-Map { <id>: { record } }.
function extractRows(roh) {
  let d = roh;
  if (d && typeof d === 'object' && !Array.isArray(d) && d.data !== undefined) {
    d = d.data;
  }
  if (d && typeof d === 'object' && !Array.isArray(d) && Array.isArray(d.rows)) {
    return d.rows;
  }
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') {
    const entries = Object.entries(d);
    if (entries.length > 0) {
      const rows = entries
        .map(([k, v]) => {
          if (v && typeof v === 'object' && !Array.isArray(v)) {
            const rec = (v.record && typeof v.record === 'object') ? v.record : v;
            return { id: rec.id ?? k, ...rec };
          }
          return null;
        })
        .filter(Boolean);
      if (rows.length > 0) return rows;
    }
    return [d];
  }
  return [];
}

const newOfferId = $('Duplicate normalisieren').first().json.offer_id;
if (!newOfferId) throw new Error('Keine neue Angebots-ID (new_offer_id) vorhanden.');

const roh = $('Vorlagen-Termine lesen').first().json;
const rows = extractRows(roh).filter(r => r && typeof r === 'object');

if (rows.length === 0) {
  const msg = 'Keine Vorlagen-Termine gefunden. Roh-Payload: ' + JSON.stringify(roh);
  console.log('[P97 Termine aufbereiten] ' + msg);
  return [{ json: { warning: true, message: msg, rawPayload: roh } }];
}

return rows.map(r => {
  const { id, offer, ...felder } = r;
  return { json: { data: { ...felder, offer: newOfferId } } };
});
